<span class="line"><span style="color:#586E75;">  &lt;</span><span style="color:#268BD2;">path</span><span style="color:#93A1A1;"> fill-rule</span><span style="color:#839496;">=</span><span style="color:#2AA198;">&quot;nonzero&quot;</span><span style="color:#93A1A1;"> fill</span><span style="color:#839496;">=</span><span style="color:#2AA198;">&quot;#e74c3c&quot;</span><span style="color:#93A1A1;"> d</span><span style="color:#839496;">=</span><span style="color:#2AA198;">&quot;</span></span>
